package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;public final class AdvancedHomeActivity extends Activity{@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_advanced_home);findViewById(R.id.pageBack).setOnClickListener(v->finish());go(R.id.openSimple,SimpleHomeActivity.class);go(R.id.openSale,SaleActivity.class);go(R.id.openRepair,RepairActivity.class);go(R.id.openProducts,ProductActivity.class);go(R.id.openPurchases,PurchaseActivity.class);go(R.id.openOnline,OnlineSaleActivity.class);go(R.id.openQuickRepair,DirectPartSaleActivity.class);go(R.id.openCash,CashActivity.class);go(R.id.openClosing,ClosingActivity.class);go(R.id.openReports,ReportsActivity.class);go(R.id.openSettings,SettingsActivity.class);}private void go(int id,Class<?> c){findViewById(id).setOnClickListener(v->startActivity(new Intent(this,c)));}}